size_t lvm2_dm_thin_vdo_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void lvm2_dm_thin_vdo_init(void) {
    g_online = true;
    kprintf("[FS/LVM2-VDO] LVM2 Thin Provisioning (dm-thin) + Inline 4KB Dedup (dm-vdo) + dm-integrity (%lu rules)\n", (unsigned long)lvm2_dm_thin_vdo_db_size());
}

bool lvm2_dm_thin_vdo_selftest(void) {
    return g_online && lvm2_dm_thin_vdo_db_size() >= 3400;
}
